def slugify(city, state_code):
    base = re.sub(r"[^a-z0-9]+", "-", f"{city}-{state_code}".lower()).strip("-")
    return base

cities = []
seen_slugs = set()
seen_names = set()
for item in RAW_CITIES:
    city, state, sc, region, mult, climate, districts, reg = item
    # Fix unique naming if city+stateCode collides
    if (city, sc) in seen_names:
        continue
    seen_names.add((city, sc))
    sl = slugify(city, sc)
    if sl in seen_slugs:
        continue
    seen_slugs.add(sl)
    low_hr = round(35 * mult)
    high_hr = round(60 * mult)
    wage_ref = round(16.5 * mult, 2)
    cities.append({
        "slug": sl,
        "city": city,
        "state": state,
        "stateCode": sc,
        "region": region,
        "costMultiplier": mult,
        "hourlyRange": [low_hr, high_hr],
        "janitorMedianWageRef": wage_ref,
        "climateWearNote": climate,
        "businessDistricts": districts,
        "regulatoryNote": reg,
    })

assert len(cities) == 150, f"Expected 150 cities, got {len(cities)}"
states = {c["stateCode"] for c in cities}
print(f"Generated {len(cities)} cities across {len(states)} states/DC.")
OUT.write_text(json.dumps(cities, indent=2))
